function contextualNotice(id,text,disabled){const bt=$(id);if(!bt)return;let note=$(id+'-context-note');if(!note){note=create('p','contextual-note');note.id=id+'-context-note';note.setAttribute('role','status');bt.parentElement.after(note);}note.textContent=text;note.hidden=!text;bt.disabled=disabled;}
function constraints(){const c=get('music'),frequencies=c.degrees.map((d,i)=>frequency(c.root,d,c.tuning,c.custom[i])),equal=c.degrees.map(d=>c.root*2**(d/12)),same=frequencies.every((f,i)=>Math.abs(f-equal[i])<1e-8);contextualNotice('compare',same?say('A and B have identical carrier frequencies. Choose another tuning or note interval.','Οι εκδοχές A/B έχουν ίδιες συχνότητες. Διάλεξε άλλο κούρδισμα ή διάστημα.' ):'',same);
 const chord=c.mode==='chord';contextualNotice('new-take',chord?say('This chord uses exact probabilities. A new random sample would not change it.','Η συγχορδία χρησιμοποιεί ακριβείς πιθανότητες. Νέο τυχαίο δείγμα δεν την αλλάζει.'):'',chord);
 const dry=c.fx.bypass||!['drive','delay','reverb'].some(k=>c.fx[k].enabled&&c.fx[k].mix>0);contextualNotice('m-fx-compare',dry?say('No audible FX are enabled. Enable an effect and release bypass.','Δεν είναι ενεργό ακουστό FX. Ενεργοποίησε εφέ και κλείσε την παράκαμψη.'):'',dry);
 for(const card of all('[data-fx-card]')){const key=card.dataset.fxCard;card.classList.toggle('fx-inactive',c.fx.bypass||!c.fx[key].enabled);let n=card.querySelector('.fx-state-note');if(!n){n=create('small','fx-state-note');card.append(n);}n.textContent=c.fx.bypass?say('Rack bypassed','Παράκαμψη αλυσίδας'):!c.fx[key].enabled?say('Effect off','Εφέ κλειστό'):c.fx[key].mix===0?say('Effect amount is zero','Ποσότητα εφέ μηδέν'):say('Effect active','Εφέ ενεργό');}
 const n=get('studio'),sameT=n.qubits.every(q=>Math.abs(q.star-q.t2)<1e-9);contextualNotice('s-compare-t2',sameT?say('T₂*=T₂ for both spins: the two envelopes coincide.','T₂*=T₂ και στα δύο spins: οι περιβάλλουσες συμπίπτουν.'):'',sameT);
 const f=mappedFrequencies(n),et=mappedFrequencies({...n,tuning:'equal'}),sameN=f.every((v,i)=>Math.abs(v-et[i])<1e-8);contextualNotice('s-compare-tuning',sameN?say('The two tunings currently give the same carrier frequencies.','Τα δύο κουρδίσματα δίνουν τώρα ίδιες συχνότητες φορέων.'):'',sameN);
}
function changed(b,c){const before=last[b];last[b]=copy(c);if(JSON.stringify(before)===JSON.stringify(c))return;const fields=Object.keys(c).filter(k=>JSON.stringify(c[k])!==JSON.stringify(before[k]));shells[b].root.dataset.changed='true';let message=say('Changed: ','Άλλαξαν: ')+fields.slice(0,4).map(k=>({theta0:'θ₀',theta1:'θ₁',phi0:'φ₀',phi1:'φ₁',basis0:say('q0 basis','βάση q0'),basis1:say('q1 basis','βάση q1'),circuit:say('circuit','κύκλωμα'),qubits:say('spin parameters','παράμετροι spins'),fx:'FX',tempo:say('rhythm','ρυθμός'),root:say('root','βασική νότα'),tuning:say('tuning','κούρδισμα')}[k]||t(k))).join(', ');
 if(b==='music'){const a=probabilities(prepare(before),before.basis0,before.basis1),p=probabilities(prepare(c),c.basis0,c.basis1),delta=Math.max(...p.map((v,i)=>Math.abs(v-a[i])));message+=' · '+(delta<1e-10?say('exact probabilities unchanged.','οι ακριβείς πιθανότητες μένουν ίδιες.'):say(`largest probability change ${(100*delta).toFixed(2)} percentage points.`,`μέγιστη αλλαγή πιθανότητας ${(100*delta).toFixed(2)} ποσοστιαίες μονάδες.`));}
 $(b+'-change-feedback').textContent=message;if(targets[b]!=='main'){targets[b]='main';if(active===b)$('shared-source-note').textContent=say('Session edited: playback/download source is now Current session. Frozen auditions are retained.','Η συνεδρία άλλαξε: επιλέχθηκε η κύρια εκδοχή για ακρόαση και λήψη. Οι παγωμένες δοκιμές διατηρούνται.');}
}
for(const b of ['music','studio']){const root=shells[b].root;root.addEventListener('focusin',e=>{if(e.target.matches('input,select,button'))showContext(b,e.target);});root.addEventListener('click',e=>{if(e.target.closest('.pipeline-grid,.gate-palette,#m-circuit [data-m-step]'))showContext(b,e.target,true);},true);for(const type of ['input','change'])root.addEventListener(type,e=>{showContext(b,e.target);queueMicrotask(()=>{constraints();refreshTransport();});});document.addEventListener(b+':configuration',e=>{changed(b,e.detail);constraints();refreshTransport();});renderContext(b);presetScope(b);$(b+'-preset-select').addEventListener('change',()=>presetScope(b));for(const el of all('input,select,button',root)){const k=helpKey(el);if(k!=='welcome'&&help[k]&&!el.dataset.help)el.dataset.help=help[k][1];}}
document.addEventListener('lab:activated',e=>{active=e.detail;queueMicrotask(()=>{refreshLayout();refreshTransport();});});document.addEventListener('lab:take',()=>queueMicrotask(refreshTransport));document.addEventListener('lab:previews',()=>queueMicrotask(refreshTransport));
document.addEventListener('lab:language',()=>{for(const b of ['music','studio']){renderContext(b);presetScope(b);}$('shared-source').dataset.key='';constraints();refreshTransport();refreshLayout();renderGuide();});window.addEventListener('resize',refreshLayout);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&explainOpen&&window.innerWidth<1280){explainOpen=false;refreshLayout();}});
