const guide=$('guide-workbench'),replay=$('guide-replay'),nmrReplay=all('button',guide).find(e=>e.textContent==='Replay NMR guide'),lessonButtons=all('[data-lesson]',guide),openButtons=all('[data-guide-bench]',guide).slice(0,2);
function renderGuide(){guide.replaceChildren();const intro=panel(say('Your first sound','Ο πρώτος σου ήχος'));intro.append(create('p','',say('Choose Music Lab, press Listen, change one polar angle and watch the probability bars. Use WAV or MP3 in the shared bar to keep the chosen sound.','Άνοιξε το Music Lab, πάτησε Ακρόαση, άλλαξε μία πολική γωνία και παρατήρησε τις πιθανότητες. Κατέβασε τον επιλεγμένο ήχο με WAV ή MP3 από την κοινή μπάρα.')));replay.textContent=say('Replay Music guide','Επανάληψη οδηγού Music');nmrReplay.textContent=say('Replay NMR guide','Επανάληψη οδηγού NMR');intro.append(replay,nmrReplay,...openButtons);guide.append(intro);
 const sections=[['Three kinds of controls','Τρεις ομάδες χειρισμών','State and experiment changes the simulated state. Sound and musical mapping translates results into audio. The shared bar listens to or exports the explicitly selected current session or frozen audition.','Η κατάσταση και το πείραμα αλλάζουν την προσομοίωση. Η μουσική και ο ήχος μεταφράζουν τα αποτελέσματα σε ήχο. Η κοινή μπάρα ακούει ή εξάγει τη ρητά επιλεγμένη κύρια εκδοχή ή παγωμένη δοκιμή.'],['Understand a control','Κατανόηση ενός χειρισμού','Focus or select a control to read its purpose in Explanation and files. The question-mark button opens that panel. A gate has no universal sound: input, readout and note mapping determine what can be heard.','Εστίασε ή επίλεξε έναν χειρισμό για να δεις την εξήγησή του. Το ερωτηματικό ανοίγει το πλαίσιο. Καμία πύλη δεν έχει καθολικό ήχο: το αποτέλεσμα εξαρτάται από την είσοδο, τη μέτρηση και τις νότες.'],['Try one phenomenon','Ένα φαινόμενο κάθε φορά','Explore opens closable experiment tabs. Visiting preserves settings; Load this example deliberately replaces the declared fields. The library keeps a return snapshot. One complete slider gesture is one Undo action.','Τα Πειράματα ανοίγουν καρτέλες με Χ. Η επίσκεψη διατηρεί τις τιμές· η Φόρτωση αναφοράς αντικαθιστά τα δηλωμένα πεδία. Η βιβλιοθήκη κρατά στιγμιότυπο επιστροφής. Μία πλήρης κίνηση slider είναι μία Αναίρεση.'],['Which sound will download','Ποιος ήχος θα κατέβει','Check Playback source in the shared bar. Frozen auditions can be renamed and exported without replacing the main circuit. The list is temporary and is lost when the page closes. Export restarts a version; it does not record live slider movements or previous FX memory.','Έλεγξε την Εκδοχή ακρόασης και λήψης στην κοινή μπάρα. Οι δοκιμές μετονομάζονται και εξάγονται χωρίς αντικατάσταση του κύριου κυκλώματος. Η λίστα χάνεται όταν κλείσει η σελίδα. Η λήψη ξεκινά την εκδοχή από την αρχή· δεν ηχογραφεί ζωντανές κινήσεις ή προηγούμενες ουρές FX.'],['Keep sound and work separately','Φύλαξη ήχου και εργασίας','WAV/MP3 keeps sound. TXT explains the frozen version. Session JSON reopens the current configuration; browser save stays on the same browser and origin. The two labs keep separate sessions.','Τα WAV/MP3 κρατούν ήχο. Το TXT εξηγεί την παγωμένη εκδοχή. Το JSON ανοίγει ξανά την κύρια ρύθμιση· η φύλαξη browser αφορά τον ίδιο browser και προέλευση. Τα δύο labs κρατούν χωριστές συνεδρίες.'],['NMR time and rhythm','Χρόνος NMR και μουσικός ρυθμός','Model milliseconds, audio seconds and BPM are distinct. The creative time mapping remains 120–180 BPM. Decay A/B freezes musical rhythm. Echo refocuses static spread, not irreversible T₂ loss. Molecule values are illustrative unless calibrated.','Τα ms του μοντέλου, τα δευτερόλεπτα ήχου και τα BPM είναι διαφορετικά μεγέθη. Η δημιουργική αντιστοίχιση παραμένει 120–180 BPM. Οι συγκρίσεις απόσβεσης παγώνουν τον μουσικό ρυθμό. Το echo επανασυμφωνεί στατική διασπορά, όχι την απώλεια T₂. Οι μοριακές τιμές είναι ενδεικτικές χωρίς βαθμονόμηση.'],['FX and tails','Εφέ και ουρές','Clean bypasses FX with the same instrument. Clean sine is a library preset that also changes oscillator, filter and level. Include FX tail allows up to 12 seconds; trim uses 0.30 seconds. Seamless looping is not guaranteed.','Χωρίς FX σημαίνει παράκαμψη εφέ με ίδιο όργανο. Το ημιτονοειδές όργανο είναι παράδειγμα βιβλιοθήκης που αλλάζει κυματομορφή, φίλτρο και στάθμη. Η διατήρηση ουράς επιτρέπει έως 12 s· η σύντομη περικοπή 0,30 s. Δεν παρέχεται εγγύηση αδιάλειπτου loop.']];
 for(const [en,el,pn,pl] of sections){const card=panel(say(en,el));card.append(create('p','',say(pn,pl)));if(en==='Try one phenomenon')card.append(...lessonButtons);guide.append(card);}}
