const sessionBox=details('Session & restore',document.createElement('div'));sessionBox.id='studio-session-details';const sessionActions=create('div','studio-buttons');sessionActions.append(...['s-save','s-restore','s-export','s-import','s-calibrate','s-reset'].map($));sessionBox.lastElementChild.append(sessionActions,$('s-import-file'),$('s-calibrate-file'));shells.studio.inspector.append(sessionBox);translations.set('Session & restore','Συνεδρία και επαναφορά');
